import local.thor.bilichannels.*;import java.util.*;
public class PhonePreviewLayoutTest {
 static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 public static void main(String[] args){int cases=0;
  for(int[] size:new int[][]{{1440,2816},{3200,1056},{1080,1800},{720,1000}})for(int count:new int[]{0,1,7,20,100})for(int pattern=0;pattern<4;pattern++){
   List<Video> videos=new ArrayList<>();for(int i=0;i<count;i++){Video v=new Video("v"+i,"","","",0,0,0,false);boolean portrait=pattern==1||pattern>1&&i%pattern==0;v.width=portrait?1080:1920;v.height=portrait?1920:1080;videos.add(v);}
   PhonePreviewLayout p=new PhonePreviewLayout(videos,size[0],size[1]);check(p.boxes.size()==count,"no fixed page cap");
   for(PreviewLayout.Box b:p.boxes){check(b.x>=0&&b.y>=0&&b.x+b.width<=size[0]+.1&&b.y+b.height<=p.height,"content bounds");check(Math.abs(b.width/(b.height-PhonePreviewLayout.captionHeight(PhonePreviewLayout.unit(size[0],size[1])))-videos.get(b.slot).aspect())<.001,"original aspect");for(PreviewLayout.Box o:p.boxes)if(o.slot!=b.slot)check(b.x+b.width<=o.x+.1||o.x+o.width<=b.x+.1||b.y+b.height<=o.y+.1||o.y+o.height<=b.y+.1,"no overlap");}
   for(float y=0;y<=p.height;y+=173){float offset=p.clamp(y,size[1]);PreviewLayout.Plan visible=p.visible(offset,size[1],66);for(PreviewLayout.Box b:visible.boxes){check(b.y+b.height>66&&b.y<size[1]+66,"only viewport intersects");check(Math.abs(b.y-(p.box(b.slot).y-offset+66))<.01,"pixel scrolling");}}
   for(boolean forward:new boolean[]{true,false})for(float offset:new float[]{0,p.clamp(p.height/2,size[1]),p.clamp(p.height,size[1])}){List<PreviewLayout.Box> warm=p.nearby(offset,size[1],66,forward,4);check(warm.size()<=4,"bounded offscreen decoders");Set<Integer> ids=new HashSet<>();for(PreviewLayout.Box b:warm){check(ids.add(b.slot)&&!p.visible(offset,size[1],66).shows(b.slot),"warm cards are distinct and offscreen");check(Math.abs(b.y-(p.box(b.slot).y-offset+66))<.01,"warming preserves exact reveal geometry");}if(count>=20&&offset==0)check(!warm.isEmpty(),"next cards prepared before scrolling");}
   if(count>=20&&pattern==0&&size[0]==1440)check(p.visible(0,size[1],0).boxes.size()>6,"more than six visible previews");
   if(count>7){List<Video> growing=new ArrayList<>(videos.subList(0,7));PhonePreviewLayout.Order order=new PhonePreviewLayout.Order(growing);PhonePreviewLayout prefix=new PhonePreviewLayout(growing,size[0],size[1],order);growing.addAll(videos.subList(7,count));order.sync();PhonePreviewLayout appended=new PhonePreviewLayout(growing,size[0],size[1],order);for(int i=0;i<7;i++)check(prefix.box(i).y==appended.box(i).y&&prefix.box(i).width==appended.box(i).width,"append preserves existing geometry");Set<Integer> slots=new HashSet<>(order.slots);check(slots.size()==count,"mixing retains every item exactly once");List<Integer> before=new ArrayList<>(order.slots);order.sync();check(before.equals(order.slots),"mixing stable while scrolling");}
   check(p.clamp(-100,size[1])==0&&p.clamp(Float.MAX_VALUE,size[1])==Math.max(0,p.height-size[1]),"scroll limits");cases++;
  }
  List<Video> delayed=new ArrayList<>();Video landscape=new Video("known","","","",0,0,0,false),portrait=new Video("pending","","","",0,0,0,false);landscape.setDimensions(1920,1080,0);delayed.add(landscape);delayed.add(portrait);
  PhonePreviewLayout.Order order=new PhonePreviewLayout.Order(delayed);PhonePreviewLayout before=new PhonePreviewLayout(delayed,1080,2000,order);check(before.box(1)==null&&before.boxes.size()==1,"unknown video is never guessed landscape");
  portrait.setDimensions(1080,1920,0);order.sync();PhonePreviewLayout ready=new PhonePreviewLayout(delayed,1080,2000,order);check(ready.box(1)!=null&&ready.box(1).height>ready.box(1).width,"first appearance already portrait");check(ready.box(0).height==before.box(0).height&&ready.box(0).y==before.box(0).y,"late metadata leaves existing cards unchanged");
  portrait.setDecoderDimensions(720,1280);landscape.setDecoderDimensions(1080,1920);order.sync();PhonePreviewLayout decoded=new PhonePreviewLayout(delayed,1080,2000,order);for(int slot=0;slot<2;slot++)check(decoded.box(slot).height==ready.box(slot).height&&decoded.box(slot).y==ready.box(slot).y,"decoder size cannot reshape published cards");
  System.out.println("PASS: "+cases+" continuous phone feeds: aspect, overlap, pixel scroll, append stability, viewport and more than six tiles");
 }
}
